package com.android.messaging.ui.conversationlist;
import android.view.MotionEvent;import android.view.View;import android.view.ViewConfiguration;import androidx.recyclerview.widget.RecyclerView;
public final class ConversationListSwipeHelper extends RecyclerView.SimpleOnItemTouchListener {public interface Callback{void swiped(int position,boolean left);}private final RecyclerView list;private final Callback cb;private final int slop;private float x,y;private View row;private ConversationListItemView item;private boolean swiping;public ConversationListSwipeHelper(RecyclerView r,Callback c){list=r;cb=c;slop=ViewConfiguration.get(r.getContext()).getScaledTouchSlop();}@Override public boolean onInterceptTouchEvent(RecyclerView rv,MotionEvent e){return handle(e);}@Override public void onTouchEvent(RecyclerView rv,MotionEvent e){handle(e);}private boolean handle(MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x=e.getX();y=e.getY();row=list.findChildViewUnder(x,y);item=row instanceof ConversationListItemView?(ConversationListItemView)row:null;swiping=false;return false;case MotionEvent.ACTION_MOVE:if(item==null)return false;float dx=e.getX()-x,dy=e.getY()-y;if(!swiping&&Math.abs(dx)>slop&&Math.abs(dx)>Math.abs(dy)*1.2f){swiping=true;list.getParent().requestDisallowInterceptTouchEvent(true);}if(swiping){item.showSwipe(dx<0);item.swipeContainer().setTranslationX(dx);item.swipeContainer().setAlpha(1f-Math.min(.28f,Math.abs(dx)/Math.max(1,item.getWidth())*.28f));return true;}return false;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:if(!swiping||item==null)return false;float total=e.getX()-x;int pos=list.getChildAdapterPosition(row);boolean go=e.getActionMasked()==MotionEvent.ACTION_UP&&Math.abs(total)>Math.max(slop*5,item.getWidth()*.25f);item.swipeContainer().animate().translationX(0).alpha(1).setDuration(120).withEndAction(item::resetSwipe).start();list.getParent().requestDisallowInterceptTouchEvent(false);if(go&&pos!=RecyclerView.NO_POSITION)cb.swiped(pos,total<0);item=null;row=null;swiping=false;return true;}return false;}}
